def transform(grid):
 h,w=len(grid),len(grid[0]); colors=set(sum(grid,[]))-{0}; shapes={}
 for c in colors:
  pts={(r,k) for r in range(h) for k in range(w) if grid[r][k]==c}
  a=min(r for r,k in pts); b=max(r for r,k in pts); l=min(k for r,k in pts); u=max(k for r,k in pts)
  candidates=[]
  def add(s):
   if pts<=s and all(grid[r][k]!=0 for r,k in s): candidates.append(s)
  add({(r,k) for r in range(a,b+1) for k in range(l,u+1)})
  add({(r,k) for r in range(a,b+1) for k in range(l,u+1) if r in (a,b) or k in (l,u)})
  for cr in range(h):
   for cc in range(w):
    rad=max(abs(r-cr)+abs(k-cc) for r,k in pts)
    if rad>max(h,w): continue
    if cr-rad<0 or cr+rad>=h or cc-rad<0 or cc+rad>=w: continue
    s={(r,k) for r in range(cr-rad,cr+rad+1) for k in range(cc-rad,cc+rad+1) if abs(r-cr)+abs(k-cc)<=rad}
    add(s)
    add({(r,k) for r,k in s if abs(r-cr)+abs(k-cc)==rad})
  shapes[c]=min(candidates,key=len) if candidates else pts
 # original top colors must be drawn first in reversed layering
 edges={c:set() for c in colors}
 for c,s in shapes.items():
  for r,k in s:
   top=grid[r][k]
   if top!=c and top in colors: edges[top].add(c)
 order=[]; remaining=set(colors)
 while remaining:
  ready=[c for c in remaining if not any(c in edges[d] for d in remaining)]
  if not ready: ready=[min(remaining)]
  for c in sorted(ready): order.append(c); remaining.remove(c)
 out=[[0]*w for _ in range(h)]
 for c in order:
  for r,k in shapes[c]: out[r][k]=c
 return out

